#!/usr/bin/env python3
"""
Nullkind Image Embedder
Run this in the same directory as index.html and the img/ folder.
It will create index_embedded.html with all images inlined.
"""
import base64, os, sys

def embed():
    # Read original
    with open('index.html', 'r', encoding='utf-8') as f:
        html = f.read()
    
    # Image paths to replace
    images = {
        "av19.jpg": "",
        "avling.jpg": "",
        "bg_corridor.jpg": "",
        "bg_room_a.jpg": "",
        "bg_room_b.jpg": "",
        "bg_supervisor.jpg": "",
        "bg_title.jpg": "",
        "bg_interior.jpg": "",
    }
    
    replacements = 0
    for filename, b64data in images.items():
        old = f'"./img/{filename}"'
        new = f'"data:image/jpeg;base64,{b64data}"'
        if old in html:
            html = html.replace(old, new)
            replacements += 1
            print(f"  Replaced {filename}")
        else:
            print(f"  WARNING: {old} not found in HTML!")
    
    # Write output
    with open('index.html', 'w', encoding='utf-8') as f:
        f.write(html)
    
    print(f"\nDone! {replacements} images embedded.")
    print(f"Output: index.html ({len(html):,} bytes)")

if __name__ == '__main__':
    embed()
